ts span{display:flex;flex-direction:column;gap:8px}.b702-project-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.b702-project-card{background:#fff;box-shadow:0 8px 24px #5a461018;transition:transform .3s}.b702-project-card:hover{transform:translateY(-7px)}.b702-project-image{display:block;height:245px;overflow:hidden}.b702-project-image img{width:100%;height:100%;object-fit:cover;transition:transform .5s}.b702-project-card:hover img{transform:scale(1.05)}.b702-project-card>div{padding:22px}.b702-project-card h3{margin:0 0 12px;font-size:18px;text-transform:uppercase}.b702-project-card h3 a{color:var(--b702-gold-dark);text-decoration:none}.b702-project-card p{color:#7b7d82}.b702-project-card p i{color:var(--b702-gold);margin-right:8px}.b702-spec{display:grid;grid-template-columns:1fr 1fr;gap:8px;color:#85878d;font-size:13px}.b702-invest{background-size:cover;background-position:center;background-attachment:fixed}.b702-activity-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.b702-activity-grid a{height:280px;background-size:cover;background-position:center;display:flex;align-items:flex-start;padding:36px;color:#fff;text-decoration:none;font-size:26px;font-weight:700}.b702-activity-grid span{border-left:3px solid #fff;padding-left:18px;max-width:260px}.b702-recommend{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.b702-project-card.compact{box-shadow:none}.b702-project-card.compact .b702-project-image{height:270px}.b702-consult{background-size:cover;background-position:center}.b702-consult-form{width:min(760px,100%);margin:auto;display:grid;grid-template-columns:1fr 1fr;gap:16px}.b702-consult-form input,.b702-consult-form textarea{width:100%;border:1px solid #ffffff77;background:#fff;padding:15px;font:inherit}.b702-consult-form textarea{grid-column:1/-1;min-height:120px;resize:vertical}.b702-consult-form button{grid-column:1/-1;width:max-content;margin:4px auto 0;cursor:pointer}.b702-partner-rail{border:1px solid #ece8de;displ